targets.expr:
sum (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase="Running"}==1
    )
)

count(
    max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace", phase="Migrating"} == 1
    )
) or vector(0)

count (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_migratable{namespace=~"$namespace"} == 0
    )
) or vector(0)

sum (
  max by (namespace, name) (
        (
            (
                d8_virtualization_virtualmachine_cpu_cores{namespace=~"$namespace"} 
                * 
                d8_virtualization_virtualmachine_cpu_core_fraction
            )
            # Stopped VM do not use CPU
            *
            on(namespace, name) group_left()
            (
                1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Stopped"})
            )
            # Pending VM do not eats RAM
            *
            on(namespace, name) group_left()
            (
            1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Pending"})
            )
        ) / 100
    )
)

sum (
  max by (namespace, name) (
        d8_virtualization_virtualdisk_capacity_bytes{namespace=~"$namespace"}
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase="Running"}==1
    )
)

sum by (namespace) (
  max by (namespace, name) (
        (
            (
                d8_virtualization_virtualmachine_cpu_cores{namespace=~"$namespace"} 
                * 
                d8_virtualization_virtualmachine_cpu_core_fraction
            )
            # Stopped VM do not use CPU
            *
            on(namespace, name) group_left()
            (
                1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Stopped"})
            )
            # Pending VM do not eats RAM
            *
            on(namespace, name) group_left()
            (
            1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Pending"})
            )
        ) / 100
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualdisk_status_phase{namespace=~"$namespace"}==1
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualimage_status_phase{namespace=~"$namespace"}==1
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualdisksnapshot_status_phase{namespace=~"$namespace"}==1
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualmachinesnapshot_status_phase{namespace=~"$namespace"}==1
    )
)

sum by (namespace) (
  max by (namespace, name) (
        d8_virtualization_virtualdisk_capacity_bytes{namespace=~"$namespace"}
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace"}==1
    )
)

sum by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase="Migrating"}==1
    )
)

count by (namespace) (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_migratable{namespace=~"$namespace"} == 0
    )
)

count by (node) (
    max by (node, namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace", node!="", phase="Running"} == 1
    )
)

label_replace(
    count by (source_node) (
        max by (namespace, name, source_node) (
            d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", source_node!="", result="InProgress"}
        )
    ),
    "node", "$1", "source_node", "(.+)"
)

label_replace(
    count by (target_node) (
        max by (namespace, name, target_node) (
            d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", target_node!="", result="InProgress"}
        )
    ),
    "node", "$1", "target_node", "(.+)"
)

count by (node) (
    max by (node, namespace, name) (
        d8_virtualization_virtualmachine_migratable{namespace=~"$namespace", node!=""} == 1
    )
)

count by (node) (
    max by (node, namespace, name) (
        d8_virtualization_virtualmachine_migratable{namespace=~"$namespace", node!=""} == 0
    )
)

count by (node) (
    max by (node, namespace, name) (
        d8_virtualization_virtualmachine_eviction_required{namespace=~"$namespace", node!=""} == 1
    )
)

max by (node) (kube_node_status_allocatable{resource="memory"})
-
(
  sum by (node) (
    max by (node, namespace, name) (
      d8_virtualization_virtualmachine_configuration_memory_size_bytes{namespace=~"$namespace"}
      + d8_virtualization_virtualmachine_configuration_memory_runtime_overhead_bytes
    )
  )
  or
  max by (node) (kube_node_status_allocatable{resource="memory"}) * 0
)

max by (namespace, name, source_node, target_node) (
    d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"}
)

max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_start_timestamp_seconds{namespace=~"$namespace"}
        * on (namespace, name) group_left ()
            max by (namespace, name) (d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"})
) * 1000

max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_data_total_bytes{namespace=~"$namespace"}
        * on (namespace, name) group_left ()
            max by (namespace, name) (d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"})
)

max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_disk_transfer_rate_bytes{namespace=~"$namespace"}
        * on (namespace, name) group_left ()
            max by (namespace, name) (d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"})
)

max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_dirty_memory_rate_bytes{namespace=~"$namespace"}
        * on (namespace, name) group_left ()
            max by (namespace, name) (d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"})
)

max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_dirty_memory_rate_bytes{namespace=~"$namespace"}
)
    /
(
    max by (namespace, name) (
        d8_virtualization_virtualmachine_migration_disk_transfer_rate_bytes{namespace=~"$namespace"}
    ) > 0
)
* on (namespace, name) group_left ()
    max by (namespace, name) (d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"})

max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress", volume_migration="true"}
)
or
max by (namespace, name) (
    d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"}
) * 0

sum by (source_node) (
    d8_virtualization_virtualmachine_migration_disk_transfer_rate_bytes{namespace=~"$namespace"}
        * on (namespace, name) group_left (source_node)
            max by (namespace, name, source_node) (
                d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"}
            )
)

sum by (target_node) (
    d8_virtualization_virtualmachine_migration_disk_transfer_rate_bytes{namespace=~"$namespace"}
        * on (namespace, name) group_left (target_node)
            max by (namespace, name, target_node) (
                d8_virtualization_virtualmachine_migration_info{namespace=~"$namespace", result="InProgress"}
            )
)

sum by (node) (
  max by (node, namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase!~"(Pending|Stopped)",node!=""} 
    )
)

sum (
  max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase!~"(Pending|Stopped)",node!=""} 
    )
)

count by (node) (
    max by (node, namespace, name) (
        d8_virtualization_virtualmachine_migratable{namespace=~"$namespace", node!=""} == 0
    )
)

count (
    max by (namespace, name) (
        d8_virtualization_virtualmachine_migratable{namespace=~"$namespace"} == 0
    )
) or vector(0)

sum by (namespace) (
  max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase!~"(Stopped|Terminating)"} 
    )
)

sum (
  max by (namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace",phase!~"(Stopped|Terminating)"} 
    )
)

sum by (phase) (
  max by (phase, namespace, name) (
        d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace"} 
    )
)

sum by (virtualmachineclass) (
    max by (namespace, name, virtualmachineclass) (
        d8_virtualization_virtualmachine_info{namespace=~"$namespace"}
    )
    * on(namespace, name) group_left()
    (
        max by (namespace, name) (
            d8_virtualization_virtualmachine_status_phase{namespace=~"$namespace", phase!~"(Pending|Stopped)"} == 1
        )
    )
)

(
  sum by (namespace) (
    max by (namespace, name) (
      rate(d8_virtualization_virtualmachine_cpu_usage_seconds_total{namespace=~"$namespace"}[$__rate_interval])
    )
  ) / 1000
)
/
(
  sum by (namespace) (
    max by (namespace, name) (
      (
        max by(namespace, name) (d8_virtualization_virtualmachine_cpu_cores{namespace=~"$namespace"})
        *
        max by(namespace, name) (d8_virtualization_virtualmachine_cpu_core_fraction{namespace=~"$namespace"})
        *
        (1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Stopped"}))
        *
        (1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Pending"}))
      ) / 100
    )
  ) / 100
)

(
  sum by (namespace) (
    max by (namespace, name) (
      d8_virtualization_virtualmachine_os_memory_total_bytes{namespace=~"$namespace"}
      -
      d8_virtualization_virtualmachine_os_memory_free_bytes{namespace=~"$namespace"}
    )
  )
)
/
(
  sum by (namespace) (
    max by(namespace, name) (d8_virtualization_virtualmachine_configuration_memory_size_bytes{namespace=~"$namespace"})
    *
    (1 + max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Migrating"}))
    *
    (1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Stopped"}))
    *
    (1 - max by(namespace, name) (d8_virtualization_virtualmachine_status_phase{phase="Pending"}))
  ) / 100
)

sum by (storageclass) (
    max by (namespace, name, storageclass) (
        d8_virtualization_virtualdisk_info{namespace=~"$namespace"}
    )
    * on(namespace, name) group_left()
    max by (namespace, name) (
        d8_virtualization_virtualdisk_capacity_bytes{namespace=~"$namespace"}
    )
)

sum by (namespace) (
  max by (namespace, name) (
        d8_virtualization_virtualdisk_capacity_bytes{namespace=~"$namespace"}
    )
)

sum (
  max by (namespace, name) (
        d8_virtualization_virtualdisk_capacity_bytes{namespace=~"$namespace"}
    )
)

sum (
    max by (name) (
        d8_virtualization_clustervirtualimage_status_phase{}==1
    )
)

sum(max by (persistentvolumeclaim) (
  max_over_time(kubelet_volume_stats_capacity_bytes{namespace="d8-virtualization", persistentvolumeclaim="dvcr"}[$__rate_interval])
))

sum(max by (persistentvolumeclaim) (
  max_over_time(kubelet_volume_stats_capacity_bytes{namespace="d8-virtualization", persistentvolumeclaim="dvcr"}[$__rate_interval]) - max_over_time(kubelet_volume_stats_available_bytes{namespace="d8-virtualization", persistentvolumeclaim="dvcr"}[$__rate_interval])
))

sum (
    max by (namespace, name) (
        d8_virtualization_virtualimage_status_phase{}==1
    )
)
